create temporary view dws_base_data_${grass_region_without_quote} as
select
    user_id
    ,case when platform in ('ios_app', 'android_app') then platform else 'others' end as platform
    ,scenario_tag
    ,local_date
from
    srdi_mart.dws_sr_data_warehouse_platform_user_level_benchmark_1d
where
    grass_region in (${grass_region})
    and local_date between date_add(${local_date}, -179) and ${local_date}
    and feature_detail = '__ALL__'
    and order_cnt > 0
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_scenario_avg_repurchase_days_180d
partition (grass_region = ${grass_region}, local_date = ${local_date})

--sql_template_spliter--
select
    ${fields_placeholder}
    ,scenario_tag

    ,avg(avg_repurchase_days_30) as avg_repurchase_days_30
    ,avg(avg_repurchase_days_60) as avg_repurchase_days_60
    ,avg(avg_repurchase_days_90) as avg_repurchase_days_90
    ,avg(avg_repurchase_days_180) as avg_repurchase_days_180

    ,percentile_approx(avg_repurchase_days_30, 0.25) as `25pct_repurchase_days_30`
    ,percentile_approx(avg_repurchase_days_60, 0.25) as `25pct_repurchase_days_60`
    ,percentile_approx(avg_repurchase_days_90, 0.25) as `25pct_repurchase_days_90`
    ,percentile_approx(avg_repurchase_days_180, 0.25) as `25pct_repurchase_days_180`

    ,percentile_approx(avg_repurchase_days_30, 0.50) as `50pct_repurchase_days_30`
    ,percentile_approx(avg_repurchase_days_60, 0.50) as `50pct_repurchase_days_60`
    ,percentile_approx(avg_repurchase_days_90, 0.50) as `50pct_repurchase_days_90`
    ,percentile_approx(avg_repurchase_days_180, 0.50) as `50pct_repurchase_days_180`

    ,percentile_approx(avg_repurchase_days_30, 0.75) as `75pct_repurchase_days_30`
    ,percentile_approx(avg_repurchase_days_60, 0.75) as `75pct_repurchase_days_60`
    ,percentile_approx(avg_repurchase_days_90, 0.75) as `75pct_repurchase_days_90`
    ,percentile_approx(avg_repurchase_days_180, 0.75) as `75pct_repurchase_days_180`

    ,percentile_approx(avg_repurchase_days_30, 0.90) as `90pct_repurchase_days_30`
    ,percentile_approx(avg_repurchase_days_60, 0.90) as `90pct_repurchase_days_60`
    ,percentile_approx(avg_repurchase_days_90, 0.90) as `90pct_repurchase_days_90`
    ,percentile_approx(avg_repurchase_days_180, 0.90) as `90pct_repurchase_days_180`

from
    (
        select
            ${fields_placeholder}
            ,scenario_tag
            ,user_id

            ,case when days_count_30 > 1 then (datediff(max_date_30, min_date_30)+0.0)/(days_count_30-1) else null end as avg_repurchase_days_30
            ,case when days_count_60 > 1 then (datediff(max_date_60, min_date_60)+0.0)/(days_count_60-1) else null end as avg_repurchase_days_60
            ,case when days_count_90 > 1 then (datediff(max_date_90, min_date_90)+0.0)/(days_count_90-1) else null end as avg_repurchase_days_90
            ,case when days_count_180 > 1 then (datediff(max_date_180, min_date_180)+0.0)/(days_count_180-1) else null end as avg_repurchase_days_180
        from
            (
                select
                    ${fields_placeholder}
                    ,scenario_tag
                    ,user_id

                    ,sum(case when local_date between date_add(${local_date}, -29) and ${local_date} then 1 else 0 end) as days_count_30
                    ,sum(case when local_date between date_add(${local_date}, -59) and ${local_date} then 1 else 0 end) as days_count_60
                    ,sum(case when local_date between date_add(${local_date}, -89) and ${local_date} then 1 else 0 end) as days_count_90
                    ,sum(case when local_date between date_add(${local_date}, -179) and ${local_date} then 1 else 0 end) as days_count_180

                    ,max(case when local_date between date_add(${local_date}, -29) and ${local_date} then local_date else null end) as max_date_30
                    ,max(case when local_date between date_add(${local_date}, -59) and ${local_date} then local_date else null end) as max_date_60
                    ,max(case when local_date between date_add(${local_date}, -89) and ${local_date} then local_date else null end) as max_date_90
                    ,max(case when local_date between date_add(${local_date}, -179) and ${local_date} then local_date else null end) as max_date_180

                    ,min(case when local_date between date_add(${local_date}, -29) and ${local_date} then local_date else null end) as min_date_30
                    ,min(case when local_date between date_add(${local_date}, -59) and ${local_date} then local_date else null end) as min_date_60
                    ,min(case when local_date between date_add(${local_date}, -89) and ${local_date} then local_date else null end) as min_date_90
                    ,min(case when local_date between date_add(${local_date}, -179) and ${local_date} then local_date else null end) as min_date_180

                from
                    (
                        select
                            ${fields_placeholder}
                            ,scenario_tag
                            ,user_id
                            ,local_date
                        from
                            dws_base_data_${grass_region_without_quote}
                        group by
                            scenario_tag
                            ,user_id
                            ,local_date
                            ${groupby_placeholder}
                    ) as t0
                group by
                    scenario_tag
                    ,user_id
                    ${groupby_placeholder}
            ) as t1

